// GENERATED by tools/make_landmask.py from Natural Earth 1:50m land minus lakes (public domain).
// 720x360 equirectangular, row 0 = 90N, col 0 = 180W. Alternating 0/1 runs (starting with 0), LEB128 varints, base64.
export const LAND_W = 720, LAND_H = 360;
export const LAND_RLE = '';
export function decodeLandMask() {
  const bin = atob(LAND_RLE), out = new Uint8Array(LAND_W * LAND_H);
  let p = 0, v = 0, i = 0;
  while (p < bin.length && i < out.length) {
    let n = 0, s = 0, b;
    do { b = bin.charCodeAt(p++); n |= (b & 0x7f) << s; s += 7; } while (b & 0x80);
    if (v) out.fill(255, i, i + n);
    i += n; v ^= 1;
  }
  return out;
}
